            <CardActionPopupHost />
        </ProjectWorkspaceAvailability>
    )
    const navigation = project ? fileTree : (
        <Box sx={{ p: 2 }}>
            <Typography color="text.secondary" variant="body2">
                No project navigation available.
            </Typography>
        </Box>
