import { Box } from '@mui/material'
import { type NodeApi, Tree } from 'react-arborist'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import type { CardTypeConfig, Card } from '../../data/data_types'
import { buildFileTree, type TreeNode } from '../../data/file_tree'
import { actionService } from '../../services/actions/action_service'
import { dialogService } from '../../services/dialog_service'
import { openFilesService } from '../../services/open_files_service'
import { telemetryService } from '../../services/telemetry/telemetry_service'
import { useActionFileTreeActions } from '../hooks/use_action_file_tree_actions'
import { useProjectState } from '../hooks/use_project_state'
import { CreateTreeItemDialog, type CreateTreeItemKind } from './create_tree_item_dialog'
import { FileTreeContext, type FileTreeContextValue } from './file_tree_context'
import { FileTreeNodeRow } from './file_tree_node_row'
import { FileTreeRow } from './file_tree_row'
import { FileTreeToolbar } from './file_tree_toolbar'
import { DEFAULT_ARCHIVED_FOLDER, DEFAULT_RELEASES_FOLDER } from '../../data/data_types'

const TREE_FALLBACK_HEIGHT = 500
const TREE_INDENT = 16
const FILE_ROW_HEIGHT = 34
const GROUP_ROW_HEIGHT = 30
const TREE_VERTICAL_PADDING = 12
const LOGS_FOLDER_NAME = 'logs'
const EMPTY_CARDS: Card[] = []
const EMPTY_REPOSITORY_FILES: string[] = []

interface FileTreeViewProps {
    actionsFolder: string
    archivedFolder?: string
    cardTypes: CardTypeConfig[]
    onCreateFolder: (parentDirectory: string, name: string) => Promise<void>
    onCreateMarkdownFile: (parentDirectory: string, name: string) => Promise<void>
    onDeleteFile: (path: string) => Promise<void>
    onDeleteFolder: (path: string) => Promise<void>
    onLeftPanelInteraction: () => void
    projectFolder: string
    releasesFolder?: string
    statusColors: Map<string, string>
    workingFolder: string
}

interface CreationRequest {
    kind: CreateTreeItemKind
    parentDirectory: string
}

function treeNodeChildren(node: TreeNode): readonly TreeNode[] | null {
    return node.kind === 'file' ? null : node.children
}

function treeRowHeight(node: NodeApi<TreeNode>): number {
    return node.data.kind === 'file' ? FILE_ROW_HEIGHT : GROUP_ROW_HEIGHT
}

function folderPath(parentFolder: string, childFolder: string) {
    return parentFolder.length > 0 ? `${parentFolder}/${childFolder}` : childFolder
}

function useElementHeight(): [React.RefObject<HTMLDivElement | null>, number] {
    const elementRef = useRef<HTMLDivElement>(null)
    const missingElementReportedRef = useRef(false)
    const [height, setHeight] = useState(TREE_FALLBACK_HEIGHT)

    useEffect(() => {
        const element = elementRef.current
        if (!element) {
            if (!missingElementReportedRef.current) {
                missingElementReportedRef.current = true
                dialogService.error(new Error('Missing file tree container'), {fallbackMessage: 'File tree could not be displayed'})
            }
            return
        }

        const updateHeight = () => {
            const measuredHeight = element.getBoundingClientRect().height
            if (measuredHeight > 0) setHeight(measuredHeight)
        }

        updateHeight()
        if (typeof ResizeObserver === 'undefined') return undefined

        const observer = new ResizeObserver(updateHeight)
        observer.observe(element)

        return () => observer.disconnect()
    }, [])

    return [elementRef, height]
}

/** Virtualized status/folder tree with compact card rows and hover-only actions. */
export function FileTreeView(props: FileTreeViewProps) {
    const {
        actionsFolder,
        archivedFolder = folderPath(props.projectFolder, DEFAULT_ARCHIVED_FOLDER),
        cardTypes,
        onCreateFolder,
        onCreateMarkdownFile,
        onDeleteFile,
        onDeleteFolder,
        onLeftPanelInteraction,
        projectFolder,
        releasesFolder = folderPath(props.projectFolder, DEFAULT_RELEASES_FOLDER),
        statusColors,
        workingFolder,
    } = props
    const { snapshot } = useProjectState()
    const activeCards = snapshot?.activeCards ?? EMPTY_CARDS
    const backgroundCards = snapshot?.backgroundCards ?? EMPTY_CARDS
    const repositoryFiles = snapshot?.repositoryFiles ?? EMPTY_REPOSITORY_FILES
    const actions = useActionFileTreeActions()
    const specialFolderPaths = useMemo(
        () => [actionsFolder, workingFolder, releasesFolder, archivedFolder],
        [actionsFolder, archivedFolder, releasesFolder, workingFolder],
    )
    const hiddenFolderPaths = useMemo(() => [folderPath(projectFolder, LOGS_FOLDER_NAME)], [projectFolder])
    const nodes = useMemo(() => buildFileTree(activeCards, backgroundCards, workingFolder, {
        actions,
        hiddenFolderPaths,
        projectFolder,
        repositoryFiles,
        specialFolderPaths,
    }), [actions, activeCards, backgroundCards, hiddenFolderPaths, projectFolder, repositoryFiles, specialFolderPaths, workingFolder])
    const cardsByPath = useMemo(() => new Map(
        [...activeCards, ...backgroundCards].map((card) => [card.path, card]),
    ), [activeCards, backgroundCards])
    const [creationRequest, setCreationRequest] = useState<CreationRequest | null>(null)
    const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null)
    const [treeContainerRef, treeHeight] = useElementHeight()

    const requestCreate = useCallback((kind: CreateTreeItemKind, parentDirectory: string) => {
        setCreationRequest({ kind, parentDirectory })
    }, [])

    const handleSelectNodes = useCallback((selectedNodes: NodeApi<TreeNode>[]) => {
        setSelectedNodeId(selectedNodes.at(0)?.id ?? null)
    }, [])

    const handleActivateNode = useCallback((node: NodeApi<TreeNode>) => {
        try {
            if (node.data.path) {
                const object = cardsByPath.get(node.data.path) ?? actionService.getActionByPath(node.data.path)
                if (!object) throw new Error(`Cannot open unknown document: ${node.data.path}`)
                setSelectedNodeId(null)
                openFilesService.openDocument(object)
                onLeftPanelInteraction()
                telemetryService.trackEvent('navigation')
                return
            }

            node.toggle()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Tree item could not be opened' })
        }
    }, [cardsByPath, onLeftPanelInteraction])

    const closeCreationDialog = () => {
        setCreationRequest(null)
    }

    const createItem = async (name: string) => {
        try {
            if (!creationRequest) throw new Error('Missing tree creation request')

            if (creationRequest.kind === 'folder') {
                await onCreateFolder(creationRequest.parentDirectory, name)
                return true
            }

            await onCreateMarkdownFile(creationRequest.parentDirectory, name)
            return true
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Tree item could not be created' })

            return false
        }
    }

    const treeContext: FileTreeContextValue = useMemo(() => ({
        cardTypes,
        cardsByPath,
        onDeleteFile,
        onDeleteFolder,
        onRequestCreate: requestCreate,
        statusColors,
    }), [cardTypes, cardsByPath, onDeleteFile, onDeleteFolder, requestCreate, statusColors])

    return (
        <FileTreeContext.Provider value={treeContext}>
            <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}>
                <FileTreeToolbar
                    nodes={nodes}
                    onRequestCreate={requestCreate}
                    projectFolder={projectFolder}
                    selectedNodeId={selectedNodeId}
                />
                <Box sx={{ display: 'flex', flex: 1, minHeight: 0, minWidth: 0 }}>
                    <Box ref={treeContainerRef} sx={{ flex: 1, minHeight: 0, minWidth: 0, overflow: 'hidden' }}>
                        <Tree<TreeNode>
                            childrenAccessor={treeNodeChildren}
                            data={nodes}
                            disableDrag
                            disableEdit
                            disableMultiSelection
                            height={treeHeight}
                            indent={TREE_INDENT}
                            onActivate={handleActivateNode}
                            onSelect={handleSelectNodes}
                            openByDefault
                            overscanCount={4}
                            paddingBottom={TREE_VERTICAL_PADDING}
                            paddingTop={TREE_VERTICAL_PADDING}
                            renderRow={FileTreeRow}
                            rowHeight={treeRowHeight}
                            selection={selectedNodeId ?? undefined}
                            width="100%"
                        >
                            {FileTreeNodeRow}
                        </Tree>
                    </Box>
                </Box>
                {creationRequest ? (
                    <CreateTreeItemDialog
                        kind={creationRequest.kind}
                        onClose={closeCreationDialog}
                        onCreate={createItem}
                        open
                        parentDirectory={creationRequest.parentDirectory}
                    />
                ) : null}
            </Box>
        </FileTreeContext.Provider>
    )
}

import {
    Box, Chip, IconButton, ListItemButton, ListItemIcon, Menu, MenuItem, Tooltip, Typography, useTheme,
} from '@mui/material'
import { alpha } from '@mui/material/styles'
import ChevronDown from 'mdi-material-ui/ChevronDown'
import ChevronRight from 'mdi-material-ui/ChevronRight'
import DeleteOutline from 'mdi-material-ui/DeleteOutline'
import DotsVertical from 'mdi-material-ui/DotsVertical'
import FileDocumentPlusOutline from 'mdi-material-ui/FileDocumentPlusOutline'
import FileDocumentOutline from 'mdi-material-ui/FileDocumentOutline'
import FolderOutline from 'mdi-material-ui/FolderOutline'
import FolderPlusOutline from 'mdi-material-ui/FolderPlusOutline'
import StarOutline from 'mdi-material-ui/StarOutline'
import { type MouseEvent, useState } from 'react'
import type { NodeRendererProps } from 'react-arborist'
import { fileContext, folderContext, type ActionContext } from '../../data/action_context'
import { getCardIdPrefix } from '../../data/card_identifiers'
import { defaultColumnAccent, type CardTypeConfig, type Card } from '../../data/data_types'
import type { TreeNode, TreeNodeKind } from '../../data/file_tree'
import { ActionEntryPoints } from '../actions/run/trigger/action_entry_points'
import { CardPathMenuItems } from '../card_view/card_path_menu_items'
import { useIsActiveDocument } from '../hooks/use_active_document'
import { useProjectReference } from '../hooks/use_project_reference'
import { useFileTreeContext } from './file_tree_context'

function nodeContext(node: TreeNode, cardTypes: CardTypeConfig[], cardsByPath: Map<string, Card>): ActionContext | null {
    if (node.kind === 'file') {
        const card = node.path ? cardsByPath.get(node.path) : undefined

        return card ? fileContext(card, cardTypes) : null
    }
    if (node.kind === 'folder' || node.kind === 'special') return folderContext(node.label, node.kind === 'special')

    return null
}

function cardTypeColor(card: Card | undefined, cardTypes: CardTypeConfig[], fallback: string) {
    const idPrefix = card ? getCardIdPrefix(card.header.id) : undefined
    const cardType = cardTypes.find((candidate) => candidate.idPrefix === idPrefix)

    return cardType?.color ?? fallback
}

function BranchIcon(props: { kind: TreeNodeKind }) {
    if (props.kind === 'special') return <StarOutline sx={{ fontSize: 16 }} />

    return <FolderOutline sx={{ fontSize: 16 }} />
}

/** A single react-arborist row preserving the file tree's existing controls and appearance. */
export function FileTreeNodeRow(props: NodeRendererProps<TreeNode>) {
    const { node, style } = props
    const { cardTypes, cardsByPath, onDeleteFile, onDeleteFolder, onRequestCreate, statusColors } = useFileTreeContext()
    const [menuAnchor, setMenuAnchor] = useState<HTMLElement | null>(null)
    const [menuPosition, setMenuPosition] = useState<{ left: number, top: number } | null>(null)
    const theme = useTheme()
    const project = useProjectReference()
    const treeNode = node.data
    const isActiveDocument = useIsActiveDocument(treeNode.path)
    const isSelected = node.isSelected || (node.tree.hasNoSelection && isActiveDocument)
    const context = nodeContext(treeNode, cardTypes, cardsByPath)
    const card = treeNode.path ? cardsByPath.get(treeNode.path) : undefined
    const isCard = !!card && (card.isActive || !!card.header.internalId)
    const accentColor = cardTypeColor(card, cardTypes, theme.palette.primary.main)
    const visibleId = card && treeNode.label.startsWith(`${card.header.id} `) ? card.header.id : null
    const visibleTitle = visibleId ? treeNode.label.slice(visibleId.length + 1) : treeNode.label
    const statusColor = treeNode.status === null ? undefined : statusColors.get(treeNode.status) ?? defaultColumnAccent(0)
    const isDeletableFolder = treeNode.kind === 'folder'
    const isMenuOpen = !!menuAnchor || !!menuPosition

    const handleRowClick = (event: MouseEvent<HTMLElement>) => {
        event.stopPropagation()
        node.select()
        if (treeNode.path) {
            node.activate()
            return
        }

        node.toggle()
    }

    const closeMenu = () => {
        setMenuAnchor(null)
        setMenuPosition(null)
    }

    const openMenu = (event: MouseEvent<HTMLButtonElement>) => {
        event.stopPropagation()
        node.select()
        setMenuAnchor(event.currentTarget)
        setMenuPosition(null)
    }

    const openContextMenu = (event: MouseEvent<HTMLElement>) => {
        event.preventDefault()
        node.select()
        setMenuAnchor(null)
        setMenuPosition({ left: event.clientX, top: event.clientY })
    }

    const requestFolder = () => {
        closeMenu()
        onRequestCreate('folder', treeNode.directoryPath)
    }

    const requestMarkdownFile = () => {
        closeMenu()
        onRequestCreate('markdownFile', treeNode.directoryPath)
    }

    const deleteFile = async (event: MouseEvent<HTMLButtonElement>) => {
        event.stopPropagation()
        if (!treeNode.path) return

        const confirmed = window.confirm(`Delete ${treeNode.path}?`)
        if (!confirmed) return

        try {
            await onDeleteFile(treeNode.path)
        } catch {
            // ProjectWorkspace owns the user-visible delete error.
        }
    }

    const deleteFolder = async (event?: MouseEvent<HTMLElement>) => {
        event?.stopPropagation()
        if (!isDeletableFolder) return

        closeMenu()
        const confirmed = window.confirm(`Delete ${treeNode.directoryPath} and all files inside it?`)
        if (!confirmed) return

        try {
            await onDeleteFolder(treeNode.directoryPath)
        } catch {
            // ProjectWorkspace owns the user-visible delete error.
        }
    }

    const itemMenu = (
        <>
            <Tooltip title="Actions">
                <IconButton aria-label="Actions" onClick={openMenu} size="small">
                    <DotsVertical fontSize="small" />
                </IconButton>
            </Tooltip>
            <Menu
                anchorEl={menuAnchor}
                anchorPosition={menuPosition ?? undefined}
                anchorReference={menuPosition ? 'anchorPosition' : 'anchorEl'}
                onClose={closeMenu}
                open={isMenuOpen}
            >
                <MenuItem onClick={requestFolder}>
                    <ListItemIcon><FolderPlusOutline fontSize="small" /></ListItemIcon>
                    New folder
                </MenuItem>
                <MenuItem onClick={requestMarkdownFile}>
                    <ListItemIcon><FileDocumentPlusOutline fontSize="small" /></ListItemIcon>
                    New Markdown file
                </MenuItem>
                {isDeletableFolder ? (
                    <MenuItem onClick={deleteFolder} sx={{ color: 'error.main' }}>
                        <ListItemIcon><DeleteOutline color="error" fontSize="small" /></ListItemIcon>
                        Delete folder
                    </MenuItem>
                ) : null}
                {context && isMenuOpen ? (
                    <ActionEntryPoints
                        context={context}
                        onMenuItemSelected={closeMenu}
                        popupAnchorElement={menuAnchor}
                        variant="menuItems"
                    />
                ) : null}
                {isCard && card ? (
                    <CardPathMenuItems cardPath={card.path} onSelected={closeMenu} rootPath={project?.rootPath} />
                ) : null}
            </Menu>
        </>
    )

    if (treeNode.kind === 'file') {
        return (
            <Box
                data-selected={isSelected ? 'true' : undefined}
                onContextMenu={openContextMenu}
                style={style}
                sx={{
                    alignItems: 'center',
                    borderRadius: 0.875,
                    boxSizing: 'border-box',
                    cursor: 'pointer',
                    display: 'flex',
                    overflow: 'hidden',
                    position: 'relative',
                    px: 0.5,
                    '& .rowActions': { opacity: 0, transition: 'opacity 120ms' },
                    '&:focus-within .rowActions, &:hover .rowActions': { opacity: 1 },
                    '&:focus-within': { bgcolor: 'action.selected' },
                    '&:hover': { bgcolor: 'action.selected' },
                    '&[data-selected="true"]': { bgcolor: alpha(theme.palette.primary.main, 0.12) },
                }}
            >
                <ListItemButton
                    onClick={handleRowClick}
                    selected={isSelected}
                    sx={{
                        borderRadius: 0.875,
                        flex: 1,
                        gap: 0.875,
                        height: '100%',
                        minWidth: 0,
                        pl: 2.25,
                        pr: 0.5,
                        py: 0,
                        '&:hover': { bgcolor: 'transparent' },
                        '&.Mui-selected, &.Mui-selected:hover': { bgcolor: 'transparent' },
                    }}
                >
                    <FileDocumentOutline sx={{ color: 'text.disabled', flexShrink: 0, fontSize: 16 }} />
                    {visibleId ? (
                        <Box
                            component="span"
                            sx={{
                                bgcolor: alpha(accentColor, 0.16),
                                borderRadius: '5px',
                                color: accentColor,
                                flexShrink: 0,
                                fontFamily: '"Roboto Mono", ui-monospace, monospace',
                                fontSize: 11.5,
                                fontWeight: 600,
                                px: 0.75,
                                py: 0.125,
                            }}
                        >
                            {visibleId}
                        </Box>
                    ) : null}
                    <Typography noWrap sx={{ color: 'text.primary', fontSize: 12.5, fontWeight: 500, minWidth: 0 }}>
                        {visibleTitle}
                    </Typography>
                </ListItemButton>
                <Box
                    className="rowActions"
                    sx={{ alignItems: 'center', bgcolor: 'inherit', bottom: 0, display: 'flex', position: 'absolute', right: 0.5, top: 0 }}
                >
                    <Tooltip title="Delete file">
                        <IconButton aria-label={`Delete ${treeNode.path}`} onClick={deleteFile} size="small" sx={{ height: 24, width: 24 }}>
                            <DeleteOutline sx={{ fontSize: 16 }} />
                        </IconButton>
                    </Tooltip>
                    {itemMenu}
                </Box>
            </Box>
        )
    }

    return (
        <Box
            data-selected={isSelected ? 'true' : undefined}
            onContextMenu={openContextMenu}
            style={style}
            sx={{
                alignItems: 'center',
                borderRadius: 0.75,
                boxSizing: 'border-box',
                cursor: 'pointer',
                display: 'flex',
                overflow: 'hidden',
                position: 'relative',
                px: 0.5,
                '& .rowActions': { opacity: 0, transition: 'opacity 120ms' },
                '&:focus-within .rowActions, &:hover .rowActions': { opacity: 1 },
                '&:focus-within': { bgcolor: 'action.selected' },
                '&:hover': { bgcolor: 'action.selected' },
                '&[data-selected="true"]': { bgcolor: alpha(theme.palette.primary.main, 0.12) },
            }}
        >
            <ListItemButton
                onClick={handleRowClick}
                selected={isSelected}
                sx={{
                    borderRadius: 0.75,
                    flex: 1,
                    gap: 0.75,
                    height: '100%',
                    minWidth: 0,
                    pr: 0.5,
                    py: 0,
                    '&:hover': { bgcolor: 'transparent' },
                    '&.Mui-selected, &.Mui-selected:hover': { bgcolor: 'transparent' },
                }}
            >
                {node.isOpen
                    ? <ChevronDown sx={{ color: 'text.secondary', fontSize: 18 }} />
                    : <ChevronRight sx={{ color: 'text.secondary', fontSize: 18 }} />}
                {statusColor ? (
                    <Box sx={{ bgcolor: statusColor, borderRadius: '3px', flexShrink: 0, height: 8, width: 8 }} />
                ) : (
                    <Box sx={{ alignItems: 'center', color: 'text.secondary', display: 'flex' }}>
                        <BranchIcon kind={treeNode.kind} />
                    </Box>
                )}
                <Typography
                    noWrap
                    sx={{ color: 'text.secondary', fontSize: 11.5, fontWeight: 700, letterSpacing: 0.6, textTransform: 'uppercase' }}
                >
                    {treeNode.label}
                </Typography>
                <Chip
                    label={treeNode.children.length}
                    size="small"
                    sx={{
                        bgcolor: 'background.paper', border: 1, borderColor: 'divider', fontSize: 11,
                        height: 19, minWidth: 22, '& .MuiChip-label': { px: 0.75 },
                    }}
                />
            </ListItemButton>
            <Box
                className="rowActions"
                sx={{ alignItems: 'center', bgcolor: 'inherit', bottom: 0, display: 'flex', position: 'absolute', right: 0.5, top: 0 }}
            >
                {isDeletableFolder ? (
                    <Tooltip title="Delete folder">
                        <IconButton
                            aria-label={`Delete ${treeNode.directoryPath}`}
                            onClick={deleteFolder}
                            size="small"
                            sx={{ height: 24, width: 24 }}
                        >
                            <DeleteOutline sx={{ fontSize: 16 }} />
                        </IconButton>
                    </Tooltip>
                ) : null}
                {itemMenu}
            </Box>
        </Box>
    )
}

import type { FocusEvent } from 'react'
import type { RowRendererProps } from 'react-arborist'
import type { TreeNode } from '../../data/file_tree'

/** Constrains react-arborist rows to the viewport so hidden actions cannot create horizontal overflow. */
export function FileTreeRow(props: RowRendererProps<TreeNode>) {
    const { attrs, children, innerRef, node } = props

    const handleFocus = (event: FocusEvent<HTMLDivElement>) => {
        event.stopPropagation()
    }

    return (
        <div
            {...attrs}
            ref={innerRef}
            onClick={node.handleClick}
            onFocus={handleFocus}
            style={{ ...attrs.style, boxSizing: 'border-box', maxWidth: '100%', minWidth: 0, overflow: 'hidden' }}
